<!doctype html>
<html lang="es">
<head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{{ $document->number }}</title><style>
body{margin:0;background:#eefbfd;color:#164e63;font:14px Arial,sans-serif}.sheet{max-width:820px;margin:32px auto;background:#fff;padding:40px;border:1px solid #a5f3fc;border-radius:18px;box-shadow:0 20px 50px #164e6320}.top{display:flex;justify-content:space-between;gap:24px;border-bottom:3px solid #06d8e8;padding-bottom:24px}.brand{font-size:28px;font-weight:800;color:#06b6d4}.box{border:2px solid #06d8e8;border-radius:12px;padding:16px;text-align:center;min-width:260px}.box b{display:block;font-size:18px}.meta{display:grid;grid-template-columns:1fr 1fr;gap:24px;padding:28px 0}.muted{color:#64748b}table{width:100%;border-collapse:collapse}th{background:#ecfeff;text-align:left}th,td{padding:12px;border-bottom:1px solid #cffafe}.right{text-align:right}.totals{margin-left:auto;margin-top:22px;width:320px}.total{font-size:20px;font-weight:800;color:#0891b2}.status{display:inline-block;padding:6px 12px;border-radius:999px;background:#cffafe;font-weight:700}button{margin-top:24px;border:0;border-radius:10px;background:#06d8e8;padding:12px 20px;font-weight:700;cursor:pointer}@media print{body{background:#fff}.sheet{margin:0;box-shadow:none;border:0}button{display:none}}@media(max-width:650px){.sheet{margin:0;border-radius:0;padding:20px}.top,.meta{grid-template-columns:1fr;display:grid}.box{min-width:0}.totals{width:100%}}
</style></head><body><main class="sheet"><div class="top"><div><div class="brand">JBTECHLINE</div><p>Comprobante electrónico</p></div><div class="box"><b>{{ strtoupper(str_replace('_', ' ', $document->type)) }}</b><strong>{{ $document->number }}</strong><p class="status">{{ strtoupper($document->status) }}</p></div></div><div class="meta"><div><b>Cliente</b><p>{{ $document->customer_name }}<br><span class="muted">Documento: {{ $document->customer_document ?: 'No indicado' }}<br>{{ $document->customer_email }}</span></p></div><div><b>Emisión</b><p>{{ optional($document->issued_at)->format('d/m/Y H:i') }}<br><span class="muted">Moneda: PEN · IGV 18%</span></p></div></div><table><thead><tr><th>Descripción</th><th>Cantidad</th><th class="right">Valor unitario</th></tr></thead><tbody>@foreach(data_get($document->payload_json, 'items', []) as $item)<tr><td>{{ $item['descripcion'] ?? '' }}</td><td>{{ $item['cantidad'] ?? '' }}</td><td class="right">S/ {{ $item['valor_unitario'] ?? '' }}</td></tr>@endforeach</tbody></table><table class="totals"><tr><td>Subtotal</td><td class="right">S/ {{ $document->subtotal }}</td></tr><tr><td>IGV</td><td class="right">S/ {{ $document->tax }}</td></tr><tr class="total"><td>Total</td><td class="right">S/ {{ $document->total }}</td></tr></table><p class="muted">Estado del proveedor: {{ data_get($document->response_json, 'payload.estado', $document->status) }}</p><button onclick="window.print()">Imprimir / guardar PDF</button></main></body></html>
